CREATE TABLE IF NOT EXISTS "ASIGNACIONES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CURSO_ID" BIGINT NOT NULL,
    "PROFESOR_PERSONA_ID" BIGINT NOT NULL,
    "DIA_SEMANA" VARCHAR(15) NOT NULL,
    "HORA_INICIO" TIME NOT NULL,
    "HORA_FIN" TIME NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "FK_ASIGNACIONES_CURSOS" FOREIGN KEY ("CURSO_ID") REFERENCES "CURSOS" ("ID"),
    CONSTRAINT "FK_ASIGNACIONES_PERSONAS" FOREIGN KEY ("PROFESOR_PERSONA_ID") REFERENCES "PERSONAS" ("ID")
);

INSERT INTO "CURSOS" ("CODIGO", "NOMBRE", "NIVEL", "LETRA", "ANIO_ESCOLAR", "JORNADA", "ACTIVO")
SELECT * FROM (
    VALUES
        ('1A-2026', '1 Basico A', '1 Basico', 'A', 2026, 'Manana', TRUE),
        ('2B-2026', '2 Basico B', '2 Basico', 'B', 2026, 'Manana', TRUE),
        ('3A-2026', '3 Basico A', '3 Basico', 'A', 2026, 'Tarde', TRUE)
) AS v("CODIGO", "NOMBRE", "NIVEL", "LETRA", "ANIO_ESCOLAR", "JORNADA", "ACTIVO")
WHERE NOT EXISTS (
    SELECT 1 FROM "CURSOS" c WHERE c."CODIGO" = v."CODIGO"
);

INSERT INTO "ASIGNACIONES" ("CURSO_ID", "PROFESOR_PERSONA_ID", "DIA_SEMANA", "HORA_INICIO", "HORA_FIN", "ACTIVO")
SELECT c."ID", p."ID", v."DIA_SEMANA", v."HORA_INICIO", v."HORA_FIN", TRUE
FROM (
    VALUES
        ('1A-2026', '11111111-1', 'LUNES', TIME '08:00', TIME '09:30'),
        ('2B-2026', '11111111-1', 'MIERCOLES', TIME '10:00', TIME '11:30'),
        ('3A-2026', '22222222-2', 'MARTES', TIME '14:00', TIME '15:30'),
        ('5B-2026', '11111111-1', 'JUEVES', TIME '08:00', TIME '09:30'),
        ('7A-2026', '22222222-2', 'VIERNES', TIME '11:00', TIME '12:30')
) AS v("CURSO_CODIGO", "PROFESOR_RUN", "DIA_SEMANA", "HORA_INICIO", "HORA_FIN")
JOIN "CURSOS" c ON c."CODIGO" = v."CURSO_CODIGO"
JOIN "PERSONAS" p ON p."RUN" = v."PROFESOR_RUN"
WHERE NOT EXISTS (
    SELECT 1
    FROM "ASIGNACIONES" a
    WHERE a."CURSO_ID" = c."ID"
      AND a."PROFESOR_PERSONA_ID" = p."ID"
      AND a."DIA_SEMANA" = v."DIA_SEMANA"
      AND a."HORA_INICIO" = v."HORA_INICIO"
      AND a."HORA_FIN" = v."HORA_FIN"
);
